  `,
})
export class ClientCredit {
  private readonly service = inject(CreditService);

  readonly clientId = input.required<number>();
  /** The client's currency; their credit is held in it. */
  readonly currency = input.required<CurrencyCode>();
  /** Emits once credit has been refunded, so other panels showing it can refresh. */
  readonly refunded = output<void>();

  protected readonly credit = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.available(params),
  });

  protected readonly saving = signal(false);
  protected readonly saved = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    amount: ['', [Validators.required, Validators.min(0.01), Validators.pattern(TWO_DECIMALS)]],
    note: ['', [Validators.maxLength(500)]],
  });

  protected invalid(name: 'amount'): boolean {
    const control = this.form.controls[name];
    return control.invalid && (control.touched || control.dirty);
  }

  /** Loads the credit again, e.g. after deposits were put toward invoices elsewhere on the page. */
  reload(): void {
    this.credit.reload();
  }

  protected submit(): void {
    this.saveError.set(null);
    this.saved.set(false);
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    const { amount, note } = this.form.getRawValue();
    this.saving.set(true);
    this.service.refund(this.clientId(), { amount: Number(amount), note: note.trim() || null }).subscribe({
      next: () => {
        this.saving.set(false);
        this.saved.set(true);
        this.form.reset();
        this.credit.reload();
        this.refunded.emit();
      },
      error: (err: { status?: number }) => {
        this.saving.set(false);
        this.saveError.set(
          err.status === 400
            ? 'The refund is more than the credit the client has.'
            : 'Could not record the refund. Please try again.',
        );
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

/** The credit a client has to spend: unused deposits plus unused credit notes, added up in `total`. */
export interface ClientCredit {
  deposits: number;
  creditNotes: number;
  total: number;
}

/** Unused credit to pay back to a client, with an optional note of why. */
export interface NewRefund {
  amount: number;
  note: string | null;
}

/** Unused credit paid back to a client, split between their held deposits and unused credit notes. */
export interface Refund {
  id: number;
  clientId: number;
  amount: number;
  fromDeposits: number;
  fromCreditNotes: number;
  /** ISO date (yyyy-MM-dd) the refund was made. */
  date: string;
  note: string | null;
}

@Injectable({ providedIn: 'root' })
export class CreditService {
  private readonly http = inject(HttpClient);

  available(clientId: number): Observable<ClientCredit> {
    return this.http.get<ClientCredit>(`/api/clients/${clientId}/credit`);
  }

  /** Pays part of the client's unused credit back to them. */
  refund(clientId: number, refund: NewRefund): Observable<Refund> {
    return this.http.post<Refund>(`/api/clients/${clientId}/refunds`, refund);
  }
}
